def bindings(net):
    rows = []
    for e in net['edges']:
        ids = [x['id'] for x in e.get('working_bindings', [])] or ['DENT-UNC-PROPAGATION']
        rows.append({'id': 'DENT-CONSTRAINT-R2-' + e['id'], 'type': 'CLAIM', 'status': 'OPEN', 'claim_type': e['claim_type'], 'review_state': 'PENDING_INDEPENDENT_REVIEW', 'claim': e['constraint'], 'annotation_for': ids[0], 'working_ids': ids, 'constraint_status': e['status'], 'constraint_id': e['id'], 'source_contract': e, 'gap': e.get('gap'), 'depends_on': [], 'no_scientific_admission': True, 'evidence': ['results/PROOF_LANE_CONSTRAINT_NET_R2/CONSTRAINT_NET_DENTAL_R2.json'], 'proposal_role': 'quantity_context_not_native_dependency'})
    payload = ''.join((json.dumps(r, ensure_ascii=False, separators=(',', ':'), allow_nan=False) + '\n' for r in rows))
    local = HERE / 'constraint_net_dental_r2_20261003.jsonl'
    local.write_text(payload)
    dest = DENT / 'notes/expansion/constraint_net_dental_r2_20261003.jsonl'
    if dest.exists() and dest.read_text() != payload:
        raise RuntimeError('Existing expansion differs; do not overwrite a potentially foreign proposal')
    if not dest.exists():
        dest.write_text(payload)
    receipt = {'path': str(dest), 'sha256': sha(dest), 'rows': len(rows), 'status': 'PENDING_INDEPENDENT_REVIEW', 'scope': 'Edge bindings only, with complete source_contract; variables/chain references remain in the net. No native status changes.'}
    dump('BINDINGS_RECEIPT.json', receipt)
    return receipt

